// -------------------- markers / annotations --------------------
function markupSelectionItems(){
  let range=null,items=selectionItems();
  try{const selection=getSelection();if(selection?.rangeCount&&!selection.isCollapsed)range=selection.getRangeAt(0)}catch{}
  if(items.length)return items;
  if(range){const header=selectedChapterHeader(range,items),item=chapterHeaderSelectionItem(range,header);if(item)return [item]}
  if(state.lastManuscriptRange){try{items=selectionItems(state.lastManuscriptRange);if(items.length)return items;const header=selectedChapterHeader(state.lastManuscriptRange,items),item=chapterHeaderSelectionItem(state.lastManuscriptRange,header);if(item)return [item]}catch{}}
  return [];
}
function markerCreatedSortValue(marker){const parsed=Date.parse(marker?.created_at||'');return Number.isFinite(parsed)?parsed:0}
let markerPanelHoverTimer=null,markerPanelHoverSourceId=null;
const MARKER_PANEL_HOVER_DELAY_MS=300;
function hideMarkerPanelHover(){
  clearTimeout(markerPanelHoverTimer);markerPanelHoverTimer=null;markerPanelHoverSourceId=null;
  const card=$('#markerPanelHoverCard');if(card)card.classList.add('hidden');
}
function positionMarkerPanelHover(card,row){
  const rect=row.getBoundingClientRect();
  card.style.visibility='hidden';card.classList.remove('hidden');
  const width=card.offsetWidth,height=card.offsetHeight,gap=8,edge=8;
  let left=rect.left-width-gap;
  if(left<edge)left=Math.min(window.innerWidth-width-edge,rect.right+gap);
  const top=Math.max(edge,Math.min(window.innerHeight-height-edge,rect.top+(rect.height-height)/2));
  card.style.left=`${Math.round(left)}px`;card.style.top=`${Math.round(top)}px`;card.style.visibility='visible';
}
function queueMarkerPanelHover(marker,row){
  hideMarkerPanelHover();
  const description=String(marker?.description||'').trim();if(!description)return;
  const id=entityId(marker.id);markerPanelHoverSourceId=id;
  markerPanelHoverTimer=setTimeout(()=>{
    if(markerPanelHoverSourceId!==id||!row.isConnected)return;
    const card=$('#markerPanelHoverCard');if(!card)return;
    card.innerHTML=`<div class="marker-panel-hover-description">${escapeHtml(description).replace(/\n/g,'<br>')}</div>`;
    positionMarkerPanelHover(card,row);
  },MARKER_PANEL_HOVER_DELAY_MS);
}
function renderMarkers(){
  hideMarkerPanelHover();
  const list=$('#labelList');if(!list)return;const add=$('#newLabelBtn'),search=$('#markerSearch');
  const allMarkers=[...state.markers].sort((a,b)=>markerCreatedSortValue(b)-markerCreatedSortValue(a)||(entityId(b.id))-(entityId(a.id)));
  const query=String(search?.value||'').trim().toLowerCase();
  const markers=allMarkers.filter(marker=>!query||`${marker.name||''} ${marker.description||''}`.toLowerCase().includes(query));
  if(search)search.disabled=!allMarkers.length;
  if(!allMarkers.length){
    state.activeMarkupClear=false;list.classList.add('empty');if(add)add.classList.add('hidden');
    list.innerHTML='<div class="manuscript-panel-empty marker-empty-state"><b>{{i18n:dynamic.html.text.b.921cbf9f}}</b><span>{{i18n:dynamic.html.text.span.29955221}}</span><button id="markerEmptyNew" data-testid="marker-empty-new" type="button">{{i18n:dynamic.html.text.button.4f7db75b}}</button></div>';
    $('#markerEmptyNew')?.addEventListener('click',()=>newMarkerDialog({items:markupSelectionItems()}));return;
  }
  list.classList.remove('empty');if(add)add.classList.remove('hidden');
  const clearRow=`<div class="marker-row marker-clear-row ${state.activeMarkupClear?'active':''}"><button type="button" class="marker-use marker-clear-use" data-marker-clear title="${escapeHtml(i18nSource(state.activeMarkupClear?'Clear markers active — click to turn off':'Clear Markers from selected prose'))}"><span class="marker-clear-chip" aria-hidden="true"></span><span class="marker-name">{{i18n:dynamic.html.text.span.2fc3f42d}}</span></button></div>`;
  list.innerHTML=clearRow+(markers.length?markers.map(marker=>`<div class="marker-row ${entityId(state.activeMarkupMarkerId)===entityId(marker.id)?'active':''}" data-marker-row="${marker.id}"><button type="button" class="marker-use" data-marker-use="${marker.id}" title="${escapeHtml(entityId(state.activeMarkupMarkerId)===entityId(marker.id)?i18nSource('Highlighter active — click to turn off'):i18nText('markup.apply_named',{name:marker.name}))}"><span class="color-chip" style="background:${marker.color}"></span><span class="marker-name">${escapeHtml(marker.name)}</span></button><button type="button" class="marker-more manuscript-item-more" data-marker-edit="${marker.id}" aria-label="${escapeHtml(i18nText('marker.configure_named',{name:marker.name}))}"><span aria-hidden="true">⋮</span></button></div>`).join(''):'<div class="marker-search-empty">{{i18n:dynamic.html.text.div.574428af}}</div>');
  $('[data-marker-clear]')?.addEventListener('click',useClearMarkers);
  $$('[data-marker-use]').forEach(button=>button.onclick=()=>useMarker(entityId(button.dataset.markerUse)));
  $$('[data-marker-edit]').forEach(button=>button.onclick=e=>{e.stopPropagation();openMarkerMenu(e,entityId(button.dataset.markerEdit))});
  $$('[data-marker-row]').forEach(row=>{
    const marker=state.markers.find(item=>entityId(item.id)===entityId(row.dataset.markerRow));
    row.onmouseenter=()=>queueMarkerPanelHover(marker,row);
    row.onmouseleave=hideMarkerPanelHover;
    row.oncontextmenu=e=>{e.preventDefault();openMarkerMenu(e,entityId(row.dataset.markerRow))};
  });
}

