function manuscriptReviewsUIValue(){return{filter:manuscriptReviewsWorkspace.filter,view:manuscriptReviewsWorkspace.view,review_id:manuscriptReviewsWorkspace.reviewId,snapshot_id:manuscriptReviewsWorkspace.snapshotId,panel_open:!!manuscriptReviewsWorkspace.panelOpen}}
