function annotationPayloadItem(item){return {block_id:item.block_id||null,chapter_id:item.block_id?null:(item.chapter_id||null),start_offset:item.start_offset,end_offset:item.end_offset,selected_text:item.selected_text||'',prefix_context:item.prefix_context||'',suffix_context:item.suffix_context||''}}
